class Hero:
    def __init__(self, name):
        self.name = name
        self.bag = set()

    def pick(self, item):
        self.bag.add(item)
        return f"{self.name} {item} aldı."

piko = Hero("Piko")
for item in ["harita", "anahtar", "harita"]:
    print(piko.pick(item))
print("Çanta:", sorted(piko.bag))

